Plan:
- Build a holiday lookup from the provided holiday date/type columns.
- For each date in the main table, write the holiday type if the date is a public holiday; otherwise write the three-letter weekday abbreviation.
- Save the workbook with plain values in the answer range.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def to_date(value):
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        return (datetime(1899, 12, 30) + timedelta(days=float(value))).date()

    text = str(value).strip()
    if not text:
        return None

    formats = (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%m/%d/%Y",
    )
    for fmt in formats:
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            pass
    return None

holidays = {}
for row in range(2, vws.max_row + 1):
    holiday_date = to_date(vws.cell(row=row, column=9).value)
    holiday_type = vws.cell(row=row, column=10).value

    if holiday_date is None or holiday_type is None:
        continue

    holiday_type = str(holiday_type).strip()
    if not holiday_type:
        continue

    if holiday_date not in holidays:
        holidays[holiday_date] = holiday_type

weekday_names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

filled = 0
for row in range(2, 76):
    cell_date = to_date(vws.cell(row=row, column=1).value)

    if cell_date is None:
        ws.cell(row=row, column=5).value = None
        continue

    if cell_date in holidays:
        result = holidays[cell_date]
    else:
        result = weekday_names[cell_date.weekday()]

    ws.cell(row=row, column=5).value = result
    filled += 1

wb.save(OUT)

print("filled rows:", filled)
print("sample values:", [(row, ws.cell(row=row, column=5).value) for row in (2, 44, 75)])
